#define ROWS_PER_WARP 4
#define MAX_K 5120
#define MAX_CHUNKS (MAX_K / 32)

extern "C" __global__ void __launch_bounds__(WARPS * 32)
fp4_gemv_pairs(const __nv_bfloat16* __restrict__ X, int x_stride,
