async function runWithRetry(key, task) {
  try {
    const r = await runs.run(key, { agent: 'worker', task });
    return { candidate: key, status: 'ok', summary: r.output };
  } catch (first) {
    const r2 = await runs.run(key + '-retry', { agent: 'worker', task });
    return { candidate: key, status: 'ok-after-retry', firstError: String(first), summary: r2.output };
  }
}

const results = await Promise.all(candidates.map(([key, task]) =>
  runWithRetry(key, task).catch(e => ({ candidate: key, status: 'failed', error: String(e) }))
));
return results;

